tokens_t parse_token(char token)
{
    if (token == '(')
    {
        return L_PAREN;
    }
    else if (token == ')')
    {
        return R_PAREN;
    }
    else if (token == '@')
    {
        return LAMBDA;
    }
    else if (token == '.')
    {
        return DOT;
    }
    else if (is_variable(token))
    {
        return VARIABLE;
    }
    else if (token == ' ')
    {
        return WHITESPACE;
    }
    else if (token == '\n')
    {
        return NEWLINE;
    }
    else if (token == '=')
    {
        return EQ;
    }
    else if (token == '"')
    {
        return QUOTE;
    }
    else if (token == ':')
    {
        return COLON;
    }
    return ERROR;
}

