AstNode *substitute(AstNode *expression, char *variable, AstNode *replacement)
{
    if (expression->type == VAR)
    {
        if (strcmp(expression->node.variable->name, variable) == 0)
        {
            return deepcopy(replacement);
        }
        return expression;
    }
    else if (expression->type == LAMBDA_EXPR)
    {
        expression->node.lambda_expr->body = substitute(expression->node.lambda_expr->body, variable, replacement);
        if (expression->node.lambda_expr->parameter != variable)
        {
            return expression;
        }
        return expression->node.lambda_expr->body;
    }
    else if (expression->type == APPLICATION)
    {
        expression->node.application->function =
            substitute(expression->node.application->function, variable, replacement);
        expression->node.application->argument =
            substitute(expression->node.application->argument, variable, replacement);
        return expression;
    }
    return expression;
}

